def check_dict_case(dict):
    if not dict:
        return False

    has_lower = has_upper = False

    for key in dict.keys():
        if not isinstance(key, str):
            return False
        if key.islower():
            has_lower = True
        if key.isupper():
            has_upper = True

    return has_lower != has_upper
